import{_ as i,o as a,c as e,aj as l}from"./framework.js";const r=JSON.parse('{"title":"常见问题 | Cli | Documentation","description":"常见问题 in Kooboo: 本页按终端中可以观察到的现象整理 Kooboo CLI 的常见问题和恢复方式。","frontmatter":{"title":"常见问题 | Cli | Documentation","description":"常见问题 in Kooboo: 本页按终端中可以观察到的现象整理 Kooboo CLI 的常见问题和恢复方式。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cli/troubleshooting.html"}]]},"headers":[],"relativePath":"zh/cli/troubleshooting.md","filePath":"cli/troubleshooting.md","lastUpdated":1786616636000}'),t={name:"zh/cli/troubleshooting.md"};function p(h,s,o,n,d,c){return a(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>本页按终端中可以观察到的现象整理 Kooboo CLI 的常见问题和恢复方式。</p><h2 id="提示缺少站点或账号配置" tabindex="-1">提示缺少站点或账号配置 <a class="header-anchor" href="#提示缺少站点或账号配置" aria-label="Permalink to &quot;提示缺少站点或账号配置&quot;">​</a></h2><p>现象：命令提示缺少 <code>KOOBOO_SITE_URL</code>、<code>KOOBOO_USERNAME</code> 或 <code>KOOBOO_PASSWORD</code>。</p><p>处理：确认当前目录是 CLI 项目，并检查项目根目录的 <code>.env</code>：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_SITE_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://example.com</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_USERNAME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=your-username</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_PASSWORD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=your-password</span></span></code></pre></div><p>重新打开终端或重新执行命令，让 CLI 再次读取项目环境。</p><h2 id="登录失败" tabindex="-1">登录失败 <a class="header-anchor" href="#登录失败" aria-label="Permalink to &quot;登录失败&quot;">​</a></h2><p>确认：</p><ul><li>站点地址使用正确的协议和域名；</li><li>账号可以登录该站点；</li><li>密码中没有意外的引号或空格；</li><li>当前账号具有操作目标资源的权限。</li></ul><p><code>kb new</code> 和 <code>kb clone</code> 的认证重试次数可以通过环境变量调整：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_AUTH_MAX_RETRIES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=3</span></span></code></pre></div><p>不要通过无限增加重试次数掩盖错误的账号或站点地址。</p><h2 id="没有匹配目标路径" tabindex="-1">没有匹配目标路径 <a class="header-anchor" href="#没有匹配目标路径" aria-label="Permalink to &quot;没有匹配目标路径&quot;">​</a></h2><p>现象：<code>pull</code> 或 <code>push</code> 提示没有资源匹配指定目标。</p><p>处理：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> images</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp-tools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -maxdepth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><p>目标路径通常省略开头的 <code>src/</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code/server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> images/gallery</span></span></code></pre></div><p>确认资源目录、文件名和大小写与<a href="./project/resources.html">项目资源与目录</a>一致。</p><h2 id="page-或-api-提示缺少-url" tabindex="-1">Page 或 API 提示缺少 URL <a class="header-anchor" href="#page-或-api-提示缺少-url" aria-label="Permalink to &quot;Page 或 API 提示缺少 URL&quot;">​</a></h2><p>Page 文件顶部需要：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- @k-url /products --&gt;</span></span></code></pre></div><p>API 文件顶部需要：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// @k-url /api/products</span></span></code></pre></div><p>补充 URL 后重新推送具体文件，避免重复执行全量推送。</p><h2 id="文件扩展名不受支持" tabindex="-1">文件扩展名不受支持 <a class="header-anchor" href="#文件扩展名不受支持" aria-label="Permalink to &quot;文件扩展名不受支持&quot;">​</a></h2><p>检查资源目录和扩展名是否匹配：</p><ul><li>Page、Layout、View 使用 <code>.html</code>；</li><li>Script 使用 <code>.js</code>；</li><li>Style 使用 <code>.css</code>；</li><li>Job 和 MCP 工具使用 <code>.ts</code>；</li><li>API、CodeBlock、PageScript 使用 <code>.ts</code> 或 <code>.js</code>。</li></ul><p>不要仅修改扩展名。文件内容也必须符合对应资源的用途。</p><h2 id="文件被-pushignore-跳过" tabindex="-1">文件被 <code>.pushignore</code> 跳过 <a class="header-anchor" href="#文件被-pushignore-跳过" aria-label="Permalink to &quot;文件被 \`.pushignore\` 跳过&quot;">​</a></h2><p>查看项目根目录的 <code>.pushignore</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1,200p&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .pushignore</span></span></code></pre></div><p>规则按顺序应用，后面的 <code>!</code> 规则可以重新包含文件。修改后使用窄范围命令重试：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path/to/resource</span></span></code></pre></div><p>注意：<code>.pushignore</code> 不影响 <code>kb sync</code>。</p><h2 id="pull-覆盖了本地修改" tabindex="-1">Pull 覆盖了本地修改 <a class="header-anchor" href="#pull-覆盖了本地修改" aria-label="Permalink to &quot;Pull 覆盖了本地修改&quot;">​</a></h2><p>先停止继续编辑，不要立即再次拉取。使用 Git 检查和恢复：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reflog</span></span></code></pre></div><p>如果修改没有提交、暂存或备份，Git 可能无法完整恢复。后续执行 <code>kb pull</code> 前，先创建提交或保护性 stash。</p><h2 id="sync-意外修改了远端" tabindex="-1">Sync 意外修改了远端 <a class="header-anchor" href="#sync-意外修改了远端" aria-label="Permalink to &quot;Sync 意外修改了远端&quot;">​</a></h2><p>立即按 <code>Ctrl+C</code> 停止同步，然后：</p><ol><li>检查 <code>.env</code> 中的站点地址；</li><li>使用 <code>git status</code> 确认最近的本地新增、修改和删除；</li><li>使用 <code>kb check</code> 查看本地与远端差异；</li><li>通过站点版本、Git 中的正确文件或已保存导出包恢复资源；</li><li>恢复完成前不要重新启动同步。</li></ol><h2 id="push-或-sync-没有处理任何变化" tabindex="-1">Push 或 Sync 没有处理任何变化 <a class="header-anchor" href="#push-或-sync-没有处理任何变化" aria-label="Permalink to &quot;Push 或 Sync 没有处理任何变化&quot;">​</a></h2><p>确认没有正在执行的 <code>kb pull</code>。项目根目录中如果残留 <code>kooboo-cli.lock</code>，并且已经确认没有拉取进程运行，可以删除该文件后重试：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kooboo-cli.lock</span></span></code></pre></div><p>然后使用具体资源路径测试：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code/server/order.ts</span></span></code></pre></div><h2 id="prune-显示的站点与当前站点不一致" tabindex="-1">Prune 显示的站点与当前站点不一致 <a class="header-anchor" href="#prune-显示的站点与当前站点不一致" aria-label="Permalink to &quot;Prune 显示的站点与当前站点不一致&quot;">​</a></h2><p>不要使用 <code>--yes</code>。检查：</p><ul><li>当前 <code>.env</code> 中的 <code>KOOBOO_SITE_URL</code>；</li><li>对账报告生成时连接的站点；</li><li>是否复制了另一个环境的报告文件。</li></ul><p>重新对当前站点运行 <code>kb check --output &lt;path&gt;</code>，再根据新报告生成清理预览。</p><h2 id="deploy-提示计划-digest-不一致" tabindex="-1">Deploy 提示计划 digest 不一致 <a class="header-anchor" href="#deploy-提示计划-digest-不一致" aria-label="Permalink to &quot;Deploy 提示计划 digest 不一致&quot;">​</a></h2><p>计划文件在生成后被修改，或文件内容损坏。不要继续执行该文件；使用原来的 commit 范围重新生成：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fro</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --write-plan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .kooboo/deploy-plan.json</span></span></code></pre></div><p>如果重新生成的计划与预期不一致，先检查 <code>from</code>、<code>to</code> 和候选 commit 中的 <code>.pushignore</code>。</p><h2 id="deploy-提示站点-id-不一致" tabindex="-1">Deploy 提示站点 ID 不一致 <a class="header-anchor" href="#deploy-提示站点-id-不一致" aria-label="Permalink to &quot;Deploy 提示站点 ID 不一致&quot;">​</a></h2><p>CLI 已登录到与计划或 <code>KOOBOO_SITE_ID</code> 不同的站点，因此在写入前停止。检查：</p><ul><li>当前项目的 <code>KOOBOO_SITE_URL</code>；</li><li><code>KOOBOO_SITE_ID</code> 是否来自同一个站点；</li><li>计划是否从另一个环境复制而来。</li></ul><p>不要为了绕过检查而删除站点 ID。确认目标环境后，使用正确的 artifact 项目和 commit 范围重新生成计划。</p><h2 id="deploy-要求-apply-deletes" tabindex="-1">Deploy 要求 <code>--apply-deletes</code> <a class="header-anchor" href="#deploy-要求-apply-deletes" aria-label="Permalink to &quot;Deploy 要求 \`--apply-deletes\`&quot;">​</a></h2><p>计划包含 Git 删除或重命名产生的旧路径删除。先执行 dry run 并审查删除项；确认后再运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --plan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .kooboo/deploy-plan.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply-deletes</span></span></code></pre></div><p>如果不接受这些删除，应修正候选 artifact commit，而不是让 CLI 忽略计划中的删除后继续上传。</p><h2 id="deploy-回执失败或退出码非零" tabindex="-1">Deploy 回执失败或退出码非零 <a class="header-anchor" href="#deploy-回执失败或退出码非零" aria-label="Permalink to &quot;Deploy 回执失败或退出码非零&quot;">​</a></h2><p>不要推进成功部署基线。打开 <code>--output</code> 指定的 JSON 文件，检查：</p><ul><li><code>operations</code> 中的 <code>failed</code> 和 <code>skipped</code> 项；</li><li><code>verification.items</code> 中的缺失资源或 hash 不一致；</li><li>目标站点、commit 范围和 <code>planDigest</code>。</li></ul><p>修复认证、资源内容或远端故障后，可以重跑同一个 <code>from → to</code>。已经成功写入的资源会再次对齐，已经删除的资源会记为 <code>already_absent</code>。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./getting-started/preparation.html">使用前准备</a></li><li><a href="./workflows/pull.html">拉取远端资源</a></li><li><a href="./workflows/push.html">推送本地资源</a></li><li><a href="./workflows/deploy.html">部署 Git 产物</a></li><li><a href="./workflows/sync.html">持续同步</a></li></ul>`,70)])])}const g=i(t,[["render",p]]);export{r as __pageData,g as default};
